        ctx.fillRect(150, 90, 110, 120)
        ctx.fillStyle = 'rgba(173,142,73,0.16)'
        ctx.fillRect(290, 110, 75, 85)
        ctx.fillStyle = 'rgba(90,171,210,0.17)'
        ctx.fillRect(110, 220, 100, 72)
